const pptx = require('pptxgenjs');
let ppt = new pptx();

// Set a premium dark theme with vibrant accents
ppt.setTheme({
    masterSlideName: 'MASTER_SLIDE',
    slideWidth: 10,
    slideHeight: 5.625, // 16:9 ratio
    fontFace: 'Helvetica Neue',
    fontSize: 14,
    majorFont: { name: 'Helvetica Neue', size: 24, bold: true },
    minorFont: { name: 'Helvetica Neue', size: 18 },
    slideNumber: { x: 0.5, y: '95%', color: 'FFFFFF' }
});

// Master Slide for premium look
ppt.defineSlide({
    masterName: 'MASTER_SLIDE',
    bkgd: '222831', // Dark Charcoal background
    objects: [
        { rect: { x: 0, y: 0, w: 10, h: 0.5, fill: { type: 'solid', color: '00ADB5' } } }, // Vibrant Cyan accent bar
        { text: { text: 'INDIA: A Land of Diversity and Innovation', options: { x: 0, y: 0, w: 10, h: 0.5, align: 'center', color: 'FFFFFF', fontSize: 28, bold: true } } },
    ],
});

// Slide 1: Title Slide (Interactive/Dynamic placeholder concept)
let slide1 = ppt.addSlide();
slide1.setMasterSlideName('MASTER_SLIDE');
slide1.addText('Incredible India', { x: 1, y: 1.5, w: 8, h: 1, fontSize: 48, color: 'EEEEEE', align: 'center', bold: true });
slide1.addText('A Journey Through History, Culture, and Future', { x: 1, y: 2.8, w: 8, h: 0.5, fontSize: 24, color: '00ADB5', align: 'center' });
// Placeholder for interactive element description
slide1.addText('✨ Interactive Element Concept: Dynamic Map visualization on next slides', { x: 0.5, y: 4.5, w: 9, h: 0.5, color: '7F8C8D', fontSize: 12 });


// Slide 2: History & Heritage
let slide2 = ppt.addSlide();
slide2.setMasterSlideName('MASTER_SLIDE');
slide2.addText('History & Heritage: A Saga of Millennia', { x: 0.5, y: 0.7, w: 9, h: 0.5, fontSize: 28, color: 'EEEEEE' });
const historyText = `Indus Valley Civilization: One of the world's earliest urban cultures (3300–1300 BCE).
Golden Age: Flourishing empires like the Mauryas and Guptas – centers of art, philosophy, and science.
Cultural Synthesis: Influence of diverse rulers, from Mughals to European traders, shaping a unique identity.`;
slide2.addText(historyText, { x: 0.5, y: 1.5, w: 8.5, h: 3, color: 'FFFFFF', fontSize: 18, bullet: true, paragraphOpts: { lineHeight: 1.5 } });


// Slide 3: Culture & Diversity
let slide3 = ppt.addSlide();
slide3.setMasterSlideName('MASTER_SLIDE');
slide3.addText('Culture & Diversity: The Soul of India', { x: 0.5, y: 0.7, w: 9, h: 0.5, fontSize: 28, color: 'EEEEEE' });
const cultureText = `Incredible Diversity: 28 States, 22 major languages, thousands of dialects, and myriad traditions.
Festivals: A vibrant tapestry of celebrations - Diwali, Holi, Eid, Christmas, and more.
Art & Spirituality: Classical dance, music, yoga, and philosophy deeply embedded in daily life.`;
slide3.addText(cultureText, { x: 0.5, y: 1.5, w: 8.5, h: 3, color: 'FFFFFF', fontSize: 18, bullet: true, paragraphOpts: { lineHeight: 1.5 } });
slide3.addNotes('Emphasize unity in diversity - interactive globe visualization could highlight cultural spread.');


// Slide 4: Economy & Innovation (Detailed Info)
let slide4 = ppt.addSlide();
slide4.setMasterSlideName('MASTER_SLIDE');
slide4.addText('Economy & Innovation: A Global Powerhouse', { x: 0.5, y: 0.7, w: 9, h: 0.5, fontSize: 28, color: 'EEEEEE' });
const economyText = `Rapid Growth: One of the fastest-growing major economies globally.
Tech Hub: World's leading destination for IT services and a booming startup ecosystem.
Key Sectors: Strong focus on technology, pharmaceuticals, agriculture, and manufacturing.`;
slide4.addText(economyText, { x: 0.5, y: 1.5, w: 8.5, h: 3, color: 'FFFFFF', fontSize: 18, bullet: true, paragraphOpts: { lineHeight: 1.5 } });
// Add a shining element concept (Simulated by bold contrasting text box)
slide4.addText('🌟 Shining Element: Startup Unicorns and Digital Adoption driving unprecedented growth 🚀', {
    x: 0.5, y: 4.5, w: 9, h: 0.5, color: 'FFD700', fontSize: 14, bold: true, align: 'center',
    fill: { type: 'solid', color: '333333' },
    border: { pt: 1, color: 'FFD700' }
});


// Slide 5: The Future
let slide5 = ppt.addSlide();
slide5.setMasterSlideName('MASTER_SLIDE');
slide5.addText('The Future: Opportunities and Vision', { x: 0.5, y: 0.7, w: 9, h: 0.5, fontSize: 28, color: 'EEEEEE' });
const futureText = `Sustainable Development: Focus on renewable energy and climate resilience.
Global Leadership: Increasing geopolitical influence and strategic partnerships.
Demographic Dividend: World's largest youth population driving future innovation and growth.`;
slide5.addText(futureText, { x: 0.5, y: 1.5, w: 8.5, h: 3, color: 'FFFFFF', fontSize: 18, bullet: true, paragraphOpts: { lineHeight: 1.5 } });


// Save the presentation
const outputPath = 'C:/Users/achal/Desktop/India_Presentation_Premium.pptx';
ppt.writeFile(outputPath).then(() => {
    console.log(`Presentation created successfully at ${outputPath}`);
}).catch(err => {
    console.error(`Error creating presentation: ${err}`);
});

